<?php declare(strict_types=1);namespace App\Controllers;use App\Core\Auth;use App\Core\Crypto;use App\Core\DB;use App\Core\Mailer;use App\Core\RateLimiter;use App\Core\Request;use App\Core\Response;use App\Core\Session;use App\Core\Totp;use App\Models\AuditLog;use App\Models\User;class AuthController extends Controller{protected string $loginView='auth/login';protected bool $adminOnly=false;public function loginForm(Request $c):Response{return $this->view($this->loginView,['meta'=>['title'=>t('auth.login')]]);}public function login(Request $i):Response{$v=mb_strtolower($i->str('email'));$w=$this->adminOnly?'/admin/login':url('/login');if(!RateLimiter::hit('login',$i->ip(),10,900)||!RateLimiter::hit('login_email',$v,8,900)){$this->flash('error',t('auth.too_many_attempts'));return $this->redirect($w);}$O=User::findByEmail($v);$q=(string)$i->input('password','');if(!$O||!Crypto::verifyPassword($q,$O['password_hash'])||!(int)$O['is_active']||$this->adminOnly&&!User::isAdminRole($O['role'])){AuditLog::log('auth.failed',$v);$this->flash('error',t('auth.invalid_credentials'));Session::set('_old',['email'=>$v]);return $this->redirect($w);}if(password_needs_rehash($O['password_hash'],PASSWORD_ARGON2ID)){User::update((int)$O['id'],['password_hash'=>Crypto::hashPassword($q)]);}$G=$i->bool('remember');if($O['two_factor']!=='none'){Session::regenerate();Session::set('2fa_pending',['user_id'=>(int)$O['id'],'remember'=>$G,'admin'=>$this->adminOnly,'at'=>time()]);if($O['two_factor']==='email'){$this->sendEmailCode($O);}return $this->redirect(url('/login/2fa'));}return $this->finishLogin($O,$G);}protected function finishLogin(array $O,bool $o):Response{Auth::login($O,$o);RateLimiter::reset('login_email',$O['email']);AuditLog::log('auth.login',$O['email'],[],(int)$O['id']);$g=Session::get('intended');Session::remove('intended');if($g&&str_starts_with((string)$g,'/')&&!str_starts_with((string)$g,'//')){return $this->redirect((string)$g);}return $this->redirect(User::isAdminRole($O['role'])&&$this->adminOnly?'/admin':url('/account'));}public function twoFactorForm(Request $a):Response{$Q=Session::get('2fa_pending');if(!$Q){return $this->redirect(url('/login'));}$b=User::find((int)$Q['user_id']);return $this->view('auth/2fa',['method'=>$b['two_factor']??'totp','meta'=>['title'=>t('auth.two_factor')]],$Q['admin']?'layouts/admin_auth':$this->layout);}public function twoFactor(Request $W):Response{$n=Session::get('2fa_pending');if(!$n||time()-(int)$n['at']>600){Session::remove('2fa_pending');return $this->redirect(url('/login'));}$b=User::find((int)$n['user_id']);if(!$b||!RateLimiter::hit('2fa',(string)$b['id'],6,600)){$this->flash('error',t('auth.too_many_attempts'));return $this->redirect(url('/login/2fa'));}$F=preg_replace('/\s+/','',$W->str('code'))??'';$P=false;if($b['two_factor']==='totp'&&$b['totp_secret']){$X=Crypto::decrypt($b['totp_secret'])??'';$P=Totp::verify($X,$F);}elseif($b['two_factor']==='email'){$P=$this->verifyEmailCode((int)$b['id'],$F);}if(!$P){AuditLog::log('auth.2fa_failed',$b['email'],[],(int)$b['id']);$this->flash('error',t('auth.invalid_code'));return $this->redirect(url('/login/2fa'));}$this->adminOnly=(bool)$n['admin'];Session::remove('2fa_pending');return $this->finishLogin($b,(bool)$n['remember']);}protected function sendEmailCode(array $b):void{$v=(string)random_int(100000,999999);DB::insert('login_codes',['user_id'=>(int)$b['id'],'code_hash'=>hash('sha256',$v),'purpose'=>'login','expires_at'=>gmdate('Y-m-d H:i:s',time()+600),'created_at'=>now()]);(new Mailer())->sendTemplate($b['email'],'two_factor_code',['user'=>$b,'code'=>$v],$b['lang']?:'fr',$b['name']);}protected function verifyEmailCode(int $n,string $t):bool{$L=DB::fetch('SELECT * FROM {{login_codes}} WHERE user_id = ? AND purpose = ? AND used_at IS NULL AND expires_at > ? ORDER BY id DESC LIMIT 1',[$n,'login',now()]);if(!$L||!hash_equals($L['code_hash'],hash('sha256',$t))){return false;}DB::update('login_codes',['used_at'=>now()],'id = ?',[$L['id']]);return true;}public function registerForm(Request $b):Response{return $this->view('auth/register',['meta'=>['title'=>t('auth.register')]]);}public function register(Request $o):Response{if(!RateLimiter::hit('register',$o->ip(),5,3600)){$this->flash('error',t('error.429'));return $this->redirect(url('/register'));}if($m=$this->validate($o,['name'=>'required|max:191','email'=>'required|email','password'=>'required|password','password_confirmation'=>'required|same:password','terms'=>'required'],url('/register'))){return $m;}if(User::findByEmail($o->str('email'))){Session::set('_errors',['email'=>t('auth.email_taken')]);Session::set('_old',['name'=>$o->str('name'),'email'=>$o->str('email')]);$this->flash('error',t('auth.email_taken'));return $this->redirect(url('/register'));}$k=User::register($o->str('email'),(string)$o->input('password'),$o->str('name'),lang(),'customer',['company'=>$o->str('company')?:null]);$W=User::find($k);AuditLog::log('auth.register',$W['email'],[],$k);$i=Crypto::randomToken();DB::insert('password_resets',['user_id'=>$k,'token_hash'=>'verify:'.substr(Crypto::hashToken($i),0,57),'expires_at'=>gmdate('Y-m-d H:i:s',time()+7*86400),'created_at'=>now()]);try{(new Mailer())->sendTemplate($W['email'],'welcome',['user'=>$W,'verify_url'=>url('/verify-email/'.$i)],lang(),$W['name']);}catch(\Throwable){}Auth::login($W);$this->flash('success',t('auth.welcome_flash'));$C=Session::get('intended');Session::remove('intended');return $this->redirect($C&&str_starts_with((string)$C,'/')?(string)$C:url('/account'));}public function verifyEmail(Request $h,string $Q):Response{$I=DB::fetch('SELECT * FROM {{password_resets}} WHERE token_hash = ? AND expires_at > ?',['verify:'.substr(Crypto::hashToken($Q),0,57),now()]);if($I){User::update((int)$I['user_id'],['email_verified_at'=>now()]);DB::delete('password_resets','id = ?',[$I['id']]);$this->flash('success',t('auth.email_verified'));}else{$this->flash('error',t('auth.token_invalid'));}return $this->redirect(Auth::check()?url('/account'):url('/login'));}public function logout(Request $k):Response{$s=Auth::user();if($s){AuditLog::log('auth.logout',$s['email'],[],(int)$s['id']);}$w=$s&&User::isAdminRole($s['role'])&&str_starts_with((string)$k->header('referer',''),rtrim((string)config('app.url'),'/').'/admin');Auth::logout();return $this->redirect($w?'/admin/login':url('/'));}public function forgotForm(Request $C):Response{return $this->view('auth/forgot',['meta'=>['title'=>t('auth.forgot_password')]]);}public function forgot(Request $n):Response{if(!RateLimiter::hit('forgot',$n->ip(),5,3600)){$this->flash('error',t('error.429'));return $this->redirect(url('/forgot-password'));}$U=User::findByEmail($n->str('email'));if($U&&(int)$U['is_active']){DB::delete('password_resets','user_id = ? AND token_hash NOT LIKE ?',[(int)$U['id'],'verify:%']);$k=Crypto::randomToken();DB::insert('password_resets',['user_id'=>(int)$U['id'],'token_hash'=>Crypto::hashToken($k),'expires_at'=>gmdate('Y-m-d H:i:s',time()+3600),'created_at'=>now()]);(new Mailer())->sendTemplate($U['email'],'password_reset',['user'=>$U,'reset_url'=>url('/reset-password/'.$k)],$U['lang']?:lang(),$U['name']);AuditLog::log('auth.reset_requested',$U['email'],[],(int)$U['id']);}$this->flash('success',t('auth.reset_sent'));return $this->redirect(url('/login'));}public function resetForm(Request $A,string $s):Response{$i=DB::fetch('SELECT * FROM {{password_resets}} WHERE token_hash = ? AND expires_at > ?',[Crypto::hashToken($s),now()]);if(!$i){$this->flash('error',t('auth.token_invalid'));return $this->redirect(url('/forgot-password'));}return $this->view('auth/reset',['token'=>$s,'meta'=>['title'=>t('auth.reset_password')]]);}public function reset(Request $d):Response{$X=$d->str('token');$A=DB::fetch('SELECT * FROM {{password_resets}} WHERE token_hash = ? AND expires_at > ?',[Crypto::hashToken($X),now()]);if(!$A){$this->flash('error',t('auth.token_invalid'));return $this->redirect(url('/forgot-password'));}if($f=$this->validate($d,['password'=>'required|password','password_confirmation'=>'required|same:password'],url('/reset-password/'.$X))){return $f;}User::update((int)$A['user_id'],['password_hash'=>Crypto::hashPassword((string)$d->input('password'))]);DB::delete('password_resets','user_id = ? AND token_hash NOT LIKE ?',[(int)$A['user_id'],'verify:%']);AuditLog::log('auth.password_reset',(string)$A['user_id'],[],(int)$A['user_id']);$this->flash('success',t('auth.password_updated'));return $this->redirect(url('/login'));}}